                target["state"]
                not in (
                    cls._RECOVERY_DIAGNOSTIC_TARGET_PRESENT,
                    cls._RECOVERY_DIAGNOSTIC_TARGET_ABSENT,
                )
                or target["matches"] != ""
                for target in targets.values()
