    cp = os.path.join(tmp.name, "cp.json"); journal = os.path.join(tmp.name, "journal.json")
    chain = os.path.join(tmp.name, "chain.json"); index = os.path.join(tmp.name, "index.json")
    progress = os.path.join(tmp.name, "progress.json"); recovery = os.path.join(tmp.name, "recovery.json")
    g = EventGraph(); g.add("root", 0, (), {"seed": 7})
    s = BranchStore(g)
    s.create("main", "root"); s.create("feature", "root")
    s.append("main", "m1", 1, {"a": 1}); s.append("feature", "f1", 2, {"b": 2})
    s.append("main", "m2", 3, {"a": 2}); s.merge("main", "feature", "M1", 4, {"c": 1})
    s.save_checkpoint(cp); s.enable_journal(cp, journal)
    s.append("main", "m3", 5, {"a": 3}); s.rotate_generation(root)
    head = None
    def grow(n, start=0):
        nonlocal head
        for i in range(n):
            head = BranchStore.append_recovery_audit_chain(root, chain, head)
            if i+1 < n:
                s.append("main", f"g{start+i}", 100+start+i, {"a": i}); s.rotate_generation(root)
    grow(5)
    BranchStore.build_recovery_audit_segments(chain, index, 2, progress, recovery)
    grow(3, 20)
    return tmp, chain, index, progress, recovery

def kill(point):
    tmp, chain, index, progress, recovery = setup()
    real_replace = os.replace; real_remove = os.remove
    real_recover = BranchStore._recover_cache_publication_locked
    real_write = BranchStore._write_cache_recovery_record
    def flaky_replace(src, dst):
        if point=="progress_replace" and os.path.realpath(dst)==os.path.realpath(progress): raise OSError("x")
        return real_replace(src, dst)
    def flaky_remove(path):
        if point=="cleanup" and os.path.basename(path).startswith(".recovery-cache-backup-"): raise OSError("x")
        return real_remove(path)
    def flaky_write(rp, data):
        ph = json.loads(data.decode())["phase"]
        if point=="record_after_index" and ph=="index": raise OSError("x")
        if point=="record_after_progress" and ph=="progress": raise OSError("x")
        return real_write(rp, data)
    def dead_recover(ip, pp, rp):
        if os.path.exists(rp): raise OSError("x")
        return real_recover(ip, pp, rp)
    with mock.patch.object(BranchStore, "_recover_cache_publication_locked", staticmethod(dead_recover)), \
         mock.patch("city_twin.branches.os.replace", flaky_replace), \
         mock.patch("city_twin.branches.os.remove", flaky_remove), \
         mock.patch.object(BranchStore, "_write_cache_recovery_record", staticmethod(flaky_write)):
        try: BranchStore.build_recovery_audit_segments(chain, index, 2, progress, recovery)
        except OSError: pass
    for pat in (".recovery-chain-segments-*.tmp", ".recovery-chain-progress-*.tmp", ".recovery-cache-record-*.tmp"):
