print("cleanup death:", j["disposition"], j["reason"], j["phase"], j["index"]["state"], j["progress"]["state"], j["backups"])
d_pc = BranchStore.recovery_diagnostic(index, progress, recovery)

# corrupt record
with open(recovery, "wb") as f: f.write(b"garbage")
j = diag(index, progress, recovery)
print("corrupt:", j["disposition"], j["reason"], "tx=", j["transaction"][:12], "phase=", repr(j["phase"]),
      j["index"]["state"], j["backups"])
assert "garbage" not in BranchStore.recovery_diagnostic(index, progress, recovery)
assert j["transaction"] == hashlib.sha256(b"garbage").hexdigest()

