tmp, chain, index, progress, recovery = kill("progress_replace")
with open(progress, "wb") as f: f.write(b"weird bytes")
j = diag(index, progress, recovery)
print("target unknown:", j["disposition"], j["reason"], j["progress"]["state"], repr(j["progress"]["matches"]))

# target missing
os.remove(progress)
try:
    diag(index, progress, recovery)
except OSError as e:
    print("missing progress -> OSError OK")

# backup missing
