    if described is None:
        if os.path.lexists(target):
            return (
                cls._RECOVERY_DIAGNOSTIC_TARGET_PRESENT,
                "",
            )
        return cls._RECOVERY_DIAGNOSTIC_TARGET_ABSENT, ""
